$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
$specs = @(Get-Content (Join-Path $root 'data/specializations.json') -Raw | ConvertFrom-Json)
$guides = @(Get-Content (Join-Path $root 'data/prompt-guidance.json') -Raw | ConvertFrom-Json)
$utf8 = [System.Text.UTF8Encoding]::new($false)

# Job-family foundations. These are shared only where the underlying work genuinely overlaps.
$families = @{
 'programming-software-development' = @{
  skills=@('Reading and modifying production code','Language-specific implementation and debugging','API and data-contract reasoning','Test design and regression checks','Version control and technical handoff')
  domains=@('Programming-language semantics and runtime behavior','Application architecture and data flow','Input validation, errors, and security','Automated testing and release practices')
  priorities=@('Learn the role''s target language and runtime by reading, modifying, and testing a small existing project.','Practice the role''s main implementation task with realistic edge cases, APIs, and data rather than isolated syntax drills.','Add tests, document setup and failure behavior, and review changes through version control before a release-style handoff.')
 }
 'artificial-intelligence-ai-services' = @{
  skills=@('Use-case scoping and success criteria','Model and workflow selection','Evaluation-set design and error analysis','API or tool integration','Privacy, safety, and human-review design')
  domains=@('Model capabilities, context limits, and failure modes','Prompting, orchestration, and structured outputs','Evaluation methods and representative test data','Data handling, safety, and deployment constraints')
  priorities=@('Study the model or AI workflow used by this role, including limitations and the types of errors it makes.','Build a small role-specific prototype and evaluate it against representative normal, ambiguous, and failure cases.','Document data flows, provider terms, human review, and measurable quality criteria before presenting a deployment recommendation.')
 }
 'ai-training-data-annotation' = @{
  skills=@('Rubric interpretation and consistent labeling','Modality-specific observation','Evidence-based scoring or transcription','Schema and quality-control checks','Uncertainty escalation and privacy handling')
  domains=@('Project taxonomy, label definitions, and edge cases','The assigned text, image, audio, video, or model-output modality','Sampling, agreement, and annotation-quality review','Consent, privacy, and task-specific safety rules')
  priorities=@('Learn the task rubric and modality conventions, then calibrate against examples with known decisions.','Practice a small batch that includes borderline cases and record why each label follows the evidence.','Run schema and consistency checks, compare disagreement patterns, and escalate unresolved rubric gaps rather than guessing.')
 }
 'writing-translation-localization' = @{
  skills=@('Audience and brief analysis','Research and source verification','Genre-specific drafting or language transfer','Terminology and style consistency','Revision, proofreading, and rights-aware delivery')
  domains=@('Target genre, audience, and publication context','Source reliability, attribution, and factual claim checking','Language register, terminology, and style conventions','Localization, accessibility, or format constraints relevant to the assignment')
  priorities=@('Study the target genre or language pair and build a short style and terminology reference before drafting.','Produce a sample using a real brief; revise for meaning, audience, accuracy, and the requested format.','Use a QA pass for sources, terminology, rights, and final-file requirements, then preserve a clear revision handoff.')
 }
 'graphic-design-visual-content' = @{
  skills=@('Visual hierarchy and composition','Typography, color, and contrast','Role-specific design software and file formats','Production-ready exports and source organization','Brief interpretation, critique, and asset-rights checks')
  domains=@('Visual communication principles for the intended medium','Grid, scale, typography, color, and accessibility','Software-native source files and export specifications','Brand, print, interface, or asset-library constraints relevant to the role')
  priorities=@('Learn the visual principles and file conventions used in this design specialty before relying on effects or templates.','Recreate a short brief at the actual output size, then compare alternatives against audience and production constraints.','Prepare editable sources and final exports, check contrast and licensing, and explain design decisions against the brief.')
 }
 'video-audio-media-production' = @{
  skills=@('Media organization and non-destructive editing','Timing, pacing, and continuity','Role-specific audio, visual, or motion techniques','Format-aware export and playback QC','Asset licensing and production handoff')
  domains=@('Timeline, frame-rate, resolution, sample-rate, or loudness standards relevant to the role','Continuity, rhythm, synchronization, and audience attention','Production software, codecs, and delivery specifications','Music, footage, voice, font, and usage-rights constraints')
  priorities=@('Learn the production workflow and delivery standards for this media specialty using a short source-to-export exercise.','Practice its distinctive timing, sound, motion, or image decisions on supplied assets and review the result on the target platform.','Check technical specs, editable project links, permissions, and playback before preparing the final package.')
 }
 'marketing-social-media-ecommerce' = @{
  skills=@('Audience and channel research','Campaign or merchandising execution','Copy, targeting, and tracking setup','Metric interpretation and controlled testing','Consent-aware data and claims review')
  domains=@('Channel mechanics and intended audience','Campaign, search, email, social, affiliate, or marketplace rules relevant to the role','Attribution limits, conversion metrics, and experiment design','Advertising disclosure, privacy, and platform policy')
  priorities=@('Study the specific channel, audience, and commercial objective this role serves; distinguish reach, intent, and conversion.','Create a small campaign or store-work sample with accurate tracking and a documented hypothesis.','Interpret results with attribution limits, test one justified change, and check platform rules and disclosures before scaling.')
 }
 'virtual-assistance-administrative-services' = @{
  skills=@('Accurate record and document handling','Calendar, inbox, spreadsheet, or CRM operations as required','Process tracking and exception management','Clear written handoffs and time-zone coordination','Confidentiality and permission boundaries')
  domains=@('The role''s system of record and approved workflow','Data validation, version control, formulas, or record hygiene','Scheduling, service-level expectations, and escalation ownership','Access control, confidentiality, and minimal-data practices')
  priorities=@('Learn the tools and approval rules used in the target administrative workflow; practice with sample records.','Complete an end-to-end task with validation, exceptions, time zones, and an auditable handoff.','Build a repeatable checklist and verify access, confidentiality, and escalation boundaries before handling live records.')
 }
 'online-teaching-training' = @{
  skills=@('Subject-matter accuracy','Learner-level diagnosis and objective setting','Explanation, modeling, and guided practice','Feedback and assessment design','Accessible online lesson facilitation')
  domains=@('Subject prerequisites and common misconceptions','Learning objectives, sequencing, and cognitive load','Assessment validity and feedback methods','Online teaching tools and accessibility')
  priorities=@('Refresh the subject concepts and identify prerequisites and common learner misconceptions.','Plan and teach a short lesson with an objective, worked example, guided practice, and a check for understanding.','Use learner evidence to adjust pacing and feedback; prepare accessible materials and a realistic follow-up task.')
 }
 'software-testing-product-testing' = @{
  skills=@('Risk-based test design and boundary coverage','Environment setup and reproducible steps','Expected-versus-actual evidence capture','Severity, usability, or compatibility judgment','Regression reporting and quality communication')
  domains=@('Target product, build, device, browser, or API behavior','Acceptance criteria, state transitions, and failure modes','Test data, reproducibility, and privacy-safe evidence','Regression, compatibility, accessibility, or model-quality methods relevant to the role')
  priorities=@('Learn the target product and its acceptance criteria; translate user risks into observable test conditions.','Run the specialty''s tests in a recorded environment and capture minimal evidence that another person can reproduce.','Retest fixes, probe adjacent regressions, and report impact and untested coverage without overstating certainty.')
 }
 'cybersecurity-bug-bounty' = @{
  skills=@('Threat modeling for the target surface','Authorization, scope, and rules-of-engagement review','Safe vulnerability analysis and validation','Evidence minimization and impact assessment','Clear remediation and responsible-disclosure reporting')
  domains=@('Target-specific security architecture and attack surface','Relevant vulnerability classes and trust boundaries','Authorization, identity, input, and data-flow controls','Rules of engagement, evidence handling, and disclosure process')
  priorities=@('Study the target technology and vulnerability classes in an authorized lab; do not test real systems without written scope.','Practice a safe, minimal proof in a controlled environment and explain impact and remediation.','Write a reproducible, redacted report and learn the relevant disclosure, legal, and authorization boundaries.')
 }
 'research-surveys-online-studies' = @{
  skills=@('Protocol or research-question comprehension','Eligibility screening and consent awareness','Structured observation and evidence logging','Honest response or source-quality judgment','Privacy and limitation reporting')
  domains=@('Study method, sampling, and eligibility rules','Consent, screener logic, and participant rights','Question wording, response validity, and attention checks','Data privacy, compensation terms, and limits of inference')
  priorities=@('Learn the study or research method and its eligibility, consent, and privacy rules before collecting information.','Practice the role''s task using a protocol or structured source log; distinguish observation from interpretation.','Check completeness and method limits, report uncertainty, and never fabricate responses or claim payment eligibility.')
 }
 'digital-products-online-selling' = @{
  skills=@('Product specification and customer-use design','Role-specific authoring or asset-production tools','Compatibility, usability, and file packaging','Accurate listings, licensing, and delivery setup','Feedback handling and basic product analytics')
  domains=@('The product format and supported software or devices','Buyer use case, onboarding, and accessibility','Marketplace licensing, file-delivery, and refund terms','Versioning, customer support, and truthful product claims')
  priorities=@('Study the buyer workflow and technical format for this product type; define what a usable first version must do.','Build and test a small product with setup instructions, compatibility checks, and a clear license.','Prepare an accurate listing and delivery path, then use buyer feedback without treating sales as guaranteed income.')
 }
 'customer-support-sales-community-management' = @{
  skills=@('Channel-appropriate customer communication','Policy, product, or community-rule application','Case triage, CRM hygiene, and follow-up','De-escalation, qualification, or moderation judgment','Consent, privacy, and escalation decisions')
  domains=@('Product/service knowledge or community policy','Case ownership, sales funnel, or moderation workflow relevant to the role','Customer identity, consent, and data-minimization practices','Escalation criteria, service metrics, and communication standards')
  priorities=@('Learn the product, policy, channel, and escalation limits before responding to customer or community cases.','Practice role-specific scenarios and record accurate outcomes, next actions, and unresolved decisions.','Review tone, privacy, and policy compliance; use service or funnel metrics without making promises beyond authority.')
 }
 'specialized-professional-remote-services' = @{
  skills=@('Discipline-specific methods and terminology','Evidence, calculation, or technical-production accuracy','Quality review and traceable documentation','Confidential data handling','Scope, qualification, licensing, and jurisdiction awareness')
  domains=@('The profession''s applicable standards, tools, and jurisdiction','Source records, calculations, drawings, or evidence used in the work','Independent review, audit trail, and error controls','Confidentiality, professional supervision, and boundaries on regulated advice')
  priorities=@('Identify the governing discipline, standards, jurisdiction, qualification limits, and review owner before taking on professional work.','Practice a bounded deliverable using traceable sources, calculations, technical tools, or primary authorities as relevant.','Run an independent accuracy check and document assumptions, confidentiality controls, and decisions requiring licensed review.')
 }
}

# Targeted profiles provide the extra technical depth needed by roles that must not collapse into their category foundation.
$targetProfiles = @{
 'frontend-developer' = @{ skills=@('Semantic HTML and accessible component structure','CSS layout systems and responsive design','JavaScript events, DOM, and state','HTTP API integration','Browser debugging and frontend performance'); domains=@('HTML document structure and semantics','CSS Grid, Flexbox, cascade, and responsive breakpoints','DOM events, browser rendering, and client-side state','HTTP requests, API errors, and web accessibility'); priorities=@('Master semantic HTML, CSS layout, and keyboard-accessible interface patterns.','Build responsive interactive components with JavaScript and handle API loading, empty, and error states.','Test in multiple viewports, measure browser performance, and ship a documented project through version control.'); distinction='Owns browser-facing behavior and presentation; differs from Backend Developer, who owns server-side logic, and UI Designer, who specifies visual interaction rather than implementing it.' }
 'backend-developer' = @{ skills=@('HTTP API design and contract validation','Server-side language and framework implementation','Relational data modeling and SQL','Authentication and authorization','Automated tests, logging, and error handling'); domains=@('Request lifecycle, HTTP methods, status codes, and API contracts','Server runtime, dependency management, and configuration','Relational schemas, transactions, and persistence','Authentication, authorization, validation, and observability'); priorities=@('Study the chosen server runtime, HTTP semantics, API contracts, and secure input handling.','Implement a small service with persistence, authorization, and tests for valid and invalid requests.','Inspect logs, measure a failure or performance issue, and document deployment and data-migration assumptions.'); distinction='Builds server-side behavior, APIs, and persistence; differs from Frontend Developer and from Full-Stack Developer, who spans both layers.' }
 'ai-response-evaluator' = @{ skills=@('Evaluation rubric interpretation','Instruction-following and relevance scoring','Factuality and citation verification','Pairwise response ranking','Hallucination, safety, and consistency detection'); domains=@('LLM response evaluation dimensions and scoring rubrics','Factuality, evidence quality, and citation validity','Pairwise preference and ranking methodology','Hallucination patterns, policy boundaries, and inter-rater consistency'); priorities=@('Learn the evaluation rubric and calibrate ratings against examples with documented reasoning.','Practice separating instruction compliance, factuality, relevance, and style; verify claims independently.','Compare responses consistently, record decisive evidence, and escalate ambiguous rubric cases.'); distinction='Judges the quality of model outputs against a rubric; differs from AI Safety Evaluator, which focuses on harm and policy risk, and LLM Evaluator, which may assess broader model behavior.' }
 'ai-safety-evaluator' = @{ skills=@('Safety policy and rubric interpretation','Harmful-content and refusal-quality assessment','Adversarial case classification','Risk severity and evidence-based annotation','Escalation and consistency review'); domains=@('AI safety taxonomies and policy boundaries','Hazard categories, severity, and context-sensitive judgments','Refusal behavior, over-refusal, and unsafe compliance','Adversarial test cases and evaluator agreement'); priorities=@('Study the applicable safety taxonomy and practice distinguishing harmful requests, safe transformations, and ambiguous intent.','Evaluate refusals and completions against policy with evidence and severity rationale.','Calibrate decisions with edge cases and document escalation boundaries without inventing policy.'); distinction='Evaluates safety risk and policy behavior specifically; differs from general AI Response Evaluation, which also scores factuality, relevance, and instruction following.' }
 'translator' = @{ skills=@('Source-text comprehension and intent analysis','Accurate meaning transfer and target-language writing','Terminology management and style-guide use','CAT tools and translation-memory workflows','Bilingual review and localization QA'); domains=@('Source and target language grammar, register, and pragmatics','Semantic equivalence, ambiguity, and domain terminology','Translation Memory, terminology bases, and CAT-tool workflows','Localization conventions, cultural adaptation, and bilingual QA'); priorities=@('Strengthen comprehension and writing in the actual language pair and choose a domain vocabulary set.','Translate a short text using a style guide and terminology list, then revise for accuracy and naturalness.','Use CAT/QA checks, compare against the source, and document unresolved ambiguity and locale decisions.'); distinction='Transfers meaning between languages while preserving context; differs from Localization Specialist, who adapts a product or experience to a locale, and Proofreader, who edits one-language text.' }
 'technical-writer' = @{ skills=@('Audience and task analysis','Information architecture and procedural writing','Technical source verification','Plain-language editing and terminology control','Versioned documentation and review workflows'); domains=@('User tasks, prerequisites, and information-seeking behavior','Documentation structures, procedures, references, and release notes','Product behavior, APIs, configuration, and authoritative source records','Terminology systems, accessibility, and documentation version control'); priorities=@('Study the product or system and identify the reader''s task, prerequisites, and failure points.','Write a procedure or reference page from verified sources and test each step against the actual workflow.','Review terminology, accessibility, versioning, and technical accuracy with a subject-matter reviewer.'); distinction='Explains how technical products or systems work; differs from general content writing by prioritizing verified instructions, reference accuracy, and user task completion.' }
 'seo-specialist' = @{ skills=@('Keyword research and search-intent mapping','On-page optimization and internal linking','Technical crawl and indexability diagnosis','Search Console and analytics interpretation','Structured data and SEO experiment measurement'); domains=@('Crawling, rendering, indexing, canonicalization, and robots directives','Query intent, SERP features, content architecture, and topical coverage','Internal links, structured data, metadata, and page performance','Search Console coverage and performance metrics with attribution limits'); priorities=@('Learn crawling, indexing, search intent, and the technical signals visible in Search Console.','Audit a site sample for crawlability, canonicalization, internal links, and content-to-intent fit.','Prioritize fixes by evidence and impact, then measure changes while accounting for seasonality and attribution limits.'); distinction='Improves organic search discovery and indexability; differs from SEM/PPC Specialist, who manages paid search campaigns and budgets.' }
 'graphic-designer' = @{ skills=@('Visual hierarchy and composition','Typography, color, and contrast','Grid and layout systems','Vector/raster production and export','Brief interpretation, critique, and asset licensing'); domains=@('Visual communication and audience perception','Typography, color relationships, contrast, and composition','Raster/vector formats, resolution, and production exports','Brand systems, usage rights, and accessible design checks'); priorities=@('Study hierarchy, typography, color, and the production formats relevant to a selected design medium.','Create multiple concepts from one brief and critique them against audience, brand, and size constraints.','Deliver editable sources and correct exports with font, stock, and licensing notes.'); distinction='Creates visual communication assets; differs from UI Designer, who designs interface states, and UX Designer, who researches and structures user flows.' }
 'ux-designer' = @{ skills=@('User interview and research planning','Journey and task-flow mapping','Information architecture and interaction design','Usability-test facilitation','Synthesis and evidence-based iteration'); domains=@('User needs, context, and research ethics','Task analysis, journeys, and information architecture','Interaction patterns, prototypes, and usability heuristics','Qualitative synthesis, usability evidence, and design iteration'); priorities=@('Learn research ethics, interview practice, and task analysis before proposing interface solutions.','Map a user journey, prototype a key flow, and test it with representative participants.','Synthesize evidence, prioritize usability problems, and explain design changes and remaining uncertainty.'); distinction='Focuses on the end-to-end usefulness and usability of a product; differs from UI Designer''s visual/interface-state work.' }
 'video-editor' = @{ skills=@('Footage logging and selects','Timeline editing, pacing, and continuity','Dialogue cleanup and audio synchronization','Caption and graphics integration','Codec, aspect-ratio, and playback QC'); domains=@('Shot selection, story structure, pacing, and continuity','Timeline, frame rate, resolution, and codec settings','Dialogue/music levels, synchronization, and caption timing','Media relinking, platform specifications, and rights clearance'); priorities=@('Learn editing fundamentals, media organization, and delivery settings for the target platform.','Edit a short brief from source footage; practice pacing, dialogue cleanup, captions, and continuity.','Export multiple required formats, inspect playback and audio, and package a relinkable project with rights notes.'); distinction='Assembles recorded footage into a coherent sequence; differs from Motion Graphics Designer, who creates animated graphic elements.' }
 'motion-graphics-designer' = @{ skills=@('Keyframe animation and easing','Typography and shape animation','Compositing and layer organization','Timing to voice or music','Render settings and asset handoff'); domains=@('Keyframes, interpolation, easing, and motion principles','Typography, vector shapes, and animated visual hierarchy','Compositing, masks, tracking, and layered project structure','Frame rate, alpha channels, rendering, and audio synchronization'); priorities=@('Study keyframes, easing, timing, and compositing in the intended motion-graphics software.','Animate a short title or explainer sequence with clear hierarchy and synchronized audio.','Review readability and render artifacts, export required codecs, and deliver editable project assets.'); distinction='Creates designed animated graphics and compositing; differs from Video Editor''s footage sequencing and editorial pacing.' }
 'virtual-assistant' = @{ skills=@('Inbox triage and email drafting','Calendar scheduling across time zones','Spreadsheet and CRM accuracy','Task tracking and concise status reporting','Confidentiality and authorization judgment'); domains=@('Inbox labels, response templates, and escalation rules','Calendar permissions, time zones, conflicts, and meeting logistics','CRM fields, spreadsheet validation, and system-of-record hygiene','Client access control, data minimization, and handoff practices'); priorities=@('Practice inbox triage, calendar coordination, and safe use of a CRM or task tracker.','Complete a simulated operations request with conflicting details and an exception log.','Create reusable checklists and provide a handoff that separates finished work from approvals needed.'); distinction='Provides broad delegated operational support; differs from Executive Assistant, which usually includes higher-trust executive coordination and decision preparation.' }
 'executive-assistant' = @{ skills=@('Executive calendar and priority management','Briefing and meeting preparation','Confidential correspondence','Decision/action tracking','Stakeholder coordination and escalation'); domains=@('Executive priorities, delegation, and decision rights','Meeting briefs, agendas, minutes, and action ownership','Complex calendars, travel/logistics, and time-zone coordination','Confidential information handling and escalation protocols'); priorities=@('Learn executive support standards, permission boundaries, and confidential information practices.','Prepare a meeting brief, reconcile calendar conflicts, and track decisions through follow-up.','Practice prioritization and escalation using time-sensitive scenarios; distinguish drafting support from decisions reserved for the executive.'); distinction='Supports executive priorities, preparation, and confidential follow-through; differs from a Virtual Assistant''s broader routine operational task mix.' }
 'english-tutor' = @{ skills=@('Learner-level and language-needs diagnosis','Communicative lesson planning','Modeling pronunciation and usage','Error correction and feedback','Progress checks and online facilitation'); domains=@('CEFR-style proficiency descriptors and skill balance','Communicative language teaching and task design','Pronunciation, grammar-in-context, vocabulary, and fluency','Formative assessment, feedback, and learner goals'); priorities=@('Review language proficiency levels and diagnose a learner''s speaking, listening, reading, and writing goals.','Plan a short communicative lesson with a model, guided practice, and meaningful learner output.','Use feedback and a progress check to adjust the next lesson; avoid promising fluency timelines or exam outcomes.'); distinction='Teaches English communication and language skills; differs from a school-subject tutor teaching a curriculum subject through English.' }
 'usability-tester' = @{ skills=@('Scenario and task writing','Think-aloud facilitation or self-report capture','Usability issue observation','Severity and user-impact judgment','Neutral, reproducible reporting'); domains=@('Task success, efficiency, errors, and satisfaction','Research protocol, participant context, and test bias','Usability heuristics and interaction friction','Observation versus interpretation and privacy-safe recording'); priorities=@('Learn how to write neutral tasks and distinguish observed behavior from interpretation.','Run a small usability session or approved test, recording task success, hesitation, and errors.','Summarize evidence by user impact and severity; avoid redesigning from one participant''s opinion alone.'); distinction='Evaluates ease of completing user tasks; differs from compatibility or functional QA, which tests technical behavior across environments.' }
 'qa-automation-engineer' = @{ skills=@('Automation framework and test architecture','Stable selectors and test data management','API/UI integration testing','CI execution and flaky-test diagnosis','Coverage, reporting, and maintainable code review'); domains=@('Test pyramid, isolation, fixtures, and test oracles','Browser/API automation frameworks and synchronization','CI pipelines, parallel execution, and environment configuration','Flaky tests, observability, and coverage trade-offs'); priorities=@('Learn a test framework and design deterministic tests with isolated data and clear assertions.','Automate a high-value user or API flow, then diagnose synchronization and flaky behavior.','Run tests in CI, report coverage limits, and keep the suite maintainable as the product changes.'); distinction='Builds and maintains automated test systems; differs from Manual QA Tester, who primarily executes and designs tests without building automation infrastructure.' }
 'bug-bounty-hunter' = @{ skills=@('Program scope and safe-harbor interpretation','Web attack-surface discovery','Authorization and access-control testing','Safe proof-of-concept validation','Severity assessment and responsible reporting'); domains=@('Bug bounty policy, in-scope assets, and excluded tests','HTTP, sessions, authentication, and authorization boundaries','Common web vulnerability classes and impact validation','Evidence minimization, severity, remediation, and disclosure'); priorities=@('Learn web security fundamentals in legal labs and read program rules before any real-world testing.','Practice a safe, minimal proof for an in-scope vulnerability without accessing other users'' data or disrupting service.','Write a reproducible, redacted report with impact and remediation; test only under explicit written authorization.'); distinction='Finds vulnerabilities within a published authorized program; differs from a penetration tester''s separately contracted, explicitly scoped assessment.' }
 'smart-contract-auditor' = @{ skills=@('Solidity or target-chain code review','State-transition and invariant reasoning','Access-control and economic-logic analysis','Static/dynamic testing and PoC construction','Severity, remediation, and audit-report writing'); domains=@('Smart-contract execution model, storage, and transaction lifecycle','Common reentrancy, access-control, arithmetic, and signature risks','Token standards, protocol invariants, and economic attack surfaces','Audit scope, reproducible tests, deployment assumptions, and remediation'); priorities=@('Study the target chain''s execution and storage model, language semantics, and common exploit patterns.','Review a small contract against invariants and test edge cases using an authorized local environment.','Write a severity-ranked finding with a safe reproducible test and remediation; never imply an audit guarantees security.'); distinction='Reviews on-chain program logic and protocol assumptions; differs from general Web Application Pentesting because chain state, transaction ordering, and economic invariants matter.' }
 'online-survey-participant' = @{ skills=@('Eligibility and screener comprehension','Informed consent and withdrawal awareness','Careful survey instruction following','Honest and internally consistent responses','Privacy and compensation-term review'); domains=@('Study screening, inclusion/exclusion criteria, and quotas','Consent, research ethics, and participant rights','Question wording, response validity, and attention checks','Data privacy, study completion records, and payment conditions'); priorities=@('Learn how screeners, eligibility rules, consent, and participant rights work before starting a study.','Practice following a survey protocol honestly, including attention checks and skip logic.','Check completion and compensation terms; protect privacy and do not fabricate eligibility or responses.'); distinction='Contributes participant responses to a defined study; differs from Market Research Participant, whose studies may emphasize consumer behavior, and User Research Participant, who tests product experiences.' }
 'user-research-participant' = @{ skills=@('Research-session instruction following','Think-aloud and experience description','Task completion and observation consent','Constructive, evidence-grounded feedback','Privacy and recording awareness'); domains=@('Usability and user-experience research protocols','Task scenarios, think-aloud methods, and participant bias','Consent for screen/audio recording and data retention','Difference between personal preference and task-observed friction'); priorities=@('Understand consent and how usability sessions collect interaction evidence.','Complete realistic task scenarios and describe expectations or confusion without trying to please the researcher.','Give specific feedback tied to observed actions and review recording/privacy terms before participating.'); distinction='Provides evidence about using a product or service; differs from a general survey respondent who may answer questions without performing usability tasks.' }
 'chat-support-agent' = @{ skills=@('Concise real-time written communication','Concurrent conversation prioritization','Knowledge-base and macro use','De-escalation and accurate ticket notes','Identity verification and privacy safeguards'); domains=@('Live-chat service workflows and response-time expectations','Approved scripts, knowledge bases, and escalation rules','Customer verification, account data, and sensitive-information controls','Queue metrics, resolution quality, and conversation handoff'); priorities=@('Learn product support rules, identity checks, and approved chat resources.','Practice concise responses in multiple concurrent scenarios while maintaining accurate case notes.','Escalate exceptions safely and review resolution quality without collecting unnecessary customer data.'); distinction='Supports customers through live written chat; differs from Email Support Agent''s asynchronous case handling and Technical Support Agent''s deeper troubleshooting.' }
 'remote-bookkeeper' = @{ skills=@('Chart-of-accounts use and transaction coding','Accounts payable and receivable processing','Bank and credit-card reconciliation','Invoice and supporting-document review','Accounting-software and audit-trail hygiene'); domains=@('Chart of accounts and double-entry bookkeeping basics','Transaction categorization, receivables, payables, and invoicing','Bank reconciliation, period close, and discrepancy investigation','Accounting-system permissions, source records, and review controls'); priorities=@('Study bookkeeping foundations, chart-of-accounts structure, and source-document controls.','Practice coding transactions and reconciling a sample bank statement in accounting software.','Review discrepancies, preserve an audit trail, and learn when tax, accounting, or jurisdiction questions require a licensed accountant.'); distinction='Records and reconciles routine financial transactions; differs from an Online Accountant who interprets standards, prepares statements, and provides higher-level accounting analysis.' }
 'online-accountant' = @{ skills=@('Financial statement preparation and analysis','Accounting standards and period-close procedures','Reconciliation and variance investigation','Tax or reporting research within jurisdictional scope','Workpaper documentation and review'); domains=@('Applicable accounting framework and reporting entity','General ledger, accruals, adjustments, and financial statements','Reconciliations, close controls, and materiality','Tax/reporting jurisdiction, client records, and professional review'); priorities=@('Establish the client''s jurisdiction, reporting framework, accounting period, and scope before analysis.','Prepare a sample reconciliation and financial statement workpaper with traceable support.','Research current primary guidance, document assumptions, and route regulated opinions or filings to an appropriately licensed professional.'); distinction='Applies accounting standards and judgment to reporting and analysis; differs from a Bookkeeper''s routine transaction recording and reconciliation.' }
 'legal-research-assistant' = @{ skills=@('Issue framing and jurisdiction/date filters','Primary legal source retrieval','Citation and quotation validation','Authority hierarchy and procedural-status checking','Concise research memoranda under attorney supervision'); domains=@('Jurisdiction-specific statutes, regulations, and court opinions','Binding versus persuasive authority and court hierarchy','Citation formats, subsequent history, and current validity','Attorney-defined questions, confidentiality, and no-independent-advice boundaries'); priorities=@('Learn the relevant jurisdiction''s primary-source databases and authority hierarchy.','Research a defined legal issue within a date range and verify each citation and quoted passage against primary material.','Write a source-linked memo that separates binding authority from secondary commentary and flags questions for supervising counsel.'); distinction='Conducts attorney-directed legal research and citation verification; does not independently advise clients or replace licensed counsel.' }
 'medical-transcriptionist' = @{ skills=@('Accurate listening and clinical terminology','Speaker and timestamp conventions','Medical spelling, abbreviations, and dosage verification','Audio-to-text proofreading','Confidential health-information handling'); domains=@('Clinical vocabulary, anatomy, medications, and common abbreviations','Verbatim versus edited transcription conventions','Speaker labeling, timestamps, and client style guides','Protected health information, secure systems, and uncertainty notation'); priorities=@('Build medical vocabulary and learn the client''s transcription conventions using non-sensitive practice audio.','Transcribe and proofread sample clinical speech, checking names and terms against permitted references.','Mark uncertainty instead of guessing and handle real recordings only through authorized secure systems.'); distinction='Converts clinical recordings into formatted text with terminology and uncertainty checks; differs from general transcription because protected health information and medical accuracy require stricter controls.' }
 'online-course-seller' = @{ skills=@('Course outcome and learner-market definition','Curriculum packaging and lesson production','Course-platform setup and release QA','Pricing/listing accuracy and learner onboarding','Support, refund, and content-rights management'); domains=@('Learner problem, course outcomes, and subject prerequisites','Module sequencing, lesson assets, assessments, and accessibility','LMS hosting, enrollment, delivery, and platform terms','Copyright, refund policies, support load, and sales uncertainty'); priorities=@('Validate a learner problem and define an observable course outcome before producing a full curriculum.','Build one sample module with lesson, practice, accessibility checks, and a learner-facing resource.','Test enrollment and course delivery, publish an accurate scope/refund policy, and review learner feedback without assuming sales.'); distinction='Packages and sells a self-paced learning product; differs from Online Course Creator, who develops curriculum and instructional materials that may be sold or delivered by others.' }
}

