$guidesById=@{}; foreach($guide in $guides){$guidesById[[string]$guide.specializationId]=$guide}
$updated=0; $profileMatches=0; $familyFallbacks=0; $unmatched=New-Object System.Collections.Generic.List[string]; $fallbackIds=New-Object System.Collections.Generic.List[string]
foreach($spec in $specs){
  $id=[string]$spec.id; $guide=$guidesById[$id]; if(!$guide){throw "Missing prompt guidance: $id"}
  $profile=$targetProfiles[$id]
  if(!$profile){
    $profile=$null
    foreach($rule in $overlays){
      if($spec.categoryId -eq $rule.cat -and $id -match $rule.re){
        $family=$families[[string]$spec.categoryId]
        $taskAnchor=@($guide.typicalTasks|Where-Object{$_}|Select-Object -First 1)
        $outputAnchor=@($guide.commonDeliverables|Where-Object{$_}|Select-Object -First 1)
        $profile=@{
          skills=@($family.skills[0..2]+$rule.skills+@($family.skills[-1])|Select-Object -Unique|Select-Object -First 9)
          domain=@($rule.domain+$family.domains|Select-Object -Unique|Select-Object -First 9)
          priorities=@("Study $($rule.domain[0]) and $($rule.domain[1]) as they apply to $($spec.title); use the relevant official standards or documentation when a current rule matters.","Practice the $($spec.title) workflow using this task: $($taskAnchor[0])","Check the result against $($rule.skills[-1]) and the expected output: $($outputAnchor[0]). Record assumptions and unresolved cases.")
          distinction="$($spec.title) focuses on $($rule.domain[0].ToLowerInvariant()); distinguish that workflow from adjacent roles before recommending tools or practice."
        }
        $profileMatches++; break
      }
    }
  }
  if(!$profile){
    $family=$families[[string]$spec.categoryId]
    if(!$family){$unmatched.Add($id);continue}
    $professionContext=[string]$guide.professionContext
    $specific=@()
    if($guide.domainKnowledge -is [array]){$specific=@($guide.domainKnowledge|Where-Object{$_ -and $_ -notmatch 'Programming language or platform named|Data flow and error handling|Testing strategy and deployment context|Applicable standards and jurisdiction|Primary sources or technical specifications'})}
    $profile=@{
      skills=@($family.skills|Select-Object -First 5)
      domain=@($specific+$family.domains|Select-Object -Unique|Select-Object -First 8)
      priorities=@($family.priorities)
      distinction="$($spec.title) applies $($spec.shortDescription.ToLowerInvariant()); the guide should explain its actual contribution model and compare only genuinely adjacent work."
    }
    $familyFallbacks++
    $fallbackIds.Add($id)
  }
  if($profile.domains){$profile.domain=$profile.domains}
  if($profile.skills.Count -lt 5 -or $profile.domain.Count -lt 4 -or $profile.priorities.Count -lt 3){throw "Incomplete role profile: $id skills=$($profile.skills.Count) domains=$($profile.domain.Count) priorities=$($profile.priorities.Count)"}
  $guide.keySkills=@($profile.skills)
  $guide.domainKnowledge=@($profile.domain)
  $guide.learningPriorities=@($profile.priorities)
  $guide.distinctiveConsiderations=@([string]$profile.distinction)
  if(!$guide.typicalTasks -or !$guide.commonDeliverables){throw "Missing task or deliverable guidance: $id"}
  if(!$guide.professionalCautions){throw "Missing professional cautions: $id"}
  $updated++
}
if($unmatched.Count){throw "No profession family defined for: $($unmatched -join ', ')"}
$json=ConvertTo-Json -InputObject $guides -Depth 40
[System.IO.File]::WriteAllText((Join-Path $root 'data/prompt-guidance.json'),$json+[Environment]::NewLine,$utf8)
Write-Output "Updated profession-specific skills, domain knowledge, learning priorities, and distinctions: $updated / $($specs.Count)"
Write-Output "Specific title profiles: $($targetProfiles.Count); role-family overlays: $profileMatches; category-context fallbacks: $familyFallbacks"
if($fallbackIds.Count){Write-Output "Fallback role IDs: $($fallbackIds -join ', ')"}
